trans = {('q0','1'): ('q1','1','R'), ('q0','0'): ('q0','0','R'), ('q1','1'): ('q1','1','R'), ('q1','0'): ('q0','0','R')}
tape = ['1','0','1']
head = 0
state = 'q0'
moves = 0
while state in ('q0','q1'):
    a = tape[head] if head < len(tape) else '_'
    if state == 'q1' and a == '_':
        break
    key = (state, a)
    if key not in trans:
        break
    ns, w, d = trans[key]
    if head < len(tape):
        tape[head] = w
    else:
        tape.append(w)
    state = ns
    moves += 1
    if d == 'R':
        head += 1
    else:
        head -= 1
accept = 1 if state == 'q1' else 0
print(moves)
print(accept)
